"""Reviews written from the previously read primary interviews and release discussions."""
from pathlib import Path
import json
from lockdown import mechanism, source

def record(rid, reviews, description, flow, packaging, sections, changes, lessons, reversals, gaps):
    return dict(robot_id=rid,review_date='2026-11-07',source_reviews=reviews,whole_robot_explanation=description,piece_flow=flow,packaging_and_motion=packaging,subsystems=sections,revisions=changes,transferable_principles=lessons,disconfirming_conditions=reversals,remaining_gaps=gaps,recommended_images=[])
def interview(url,title,locator,facts,limits):
    return source(url,title,locator,'Read available English captions of the team interview. Times refer to the source video.',facts,limits)

